// Text it wrote: the first 64 KiB.
type AgentEventMessage string

// AgentEventToolCall is a member of [AgentEventEvent], with the fields of [ToolCall].
//
// A command it ran, a file it read or edited, a search...
type AgentEventToolCall ToolCall

// AgentEventToolResult is a member of [AgentEventEvent], with the fields of [ToolResult].
type AgentEventToolResult ToolResult

// AgentEventTurnEnd is a member of [AgentEventEvent], with the fields of [AgentTurn].
//
// The turn as it ended.
type AgentEventTurnEnd AgentTurn

// AgentEventCaughtUp is a member of [AgentEventEvent], with the fields of [CaughtUp].
//
// [Client.WatchConversation] only, once: the events before it were there when the stream
// opened; what follows is live. Its seq is the last one sent, or
// [WatchConversationRequest.AfterSeq] when none was; or the conversation's last, when that is
// before [WatchConversationRequest.AfterSeq]: a sandbox that lost its memory may have lost its
// last events, and the next ones take their seq again.
type AgentEventCaughtUp CaughtUp

type CaughtUp struct{}

// A call may have no [ToolResult]: an agent can leave a command running and go on without it.
type ToolCall struct {
	ToolCallID string
	// As the agent names it: "Bash", "Edit", "shell".
	Name string
	// JSON; over 64 KiB: {"truncated": true, "bytes": <its size>}.
	Input string
}

type ToolResult struct {
	ToolCallID string
	// The first 64 KiB.
	Output string
	Failed bool
}

// LimitReached is a detail of an [Error]: [Error.LimitReached].
//
// [CodeResourceExhausted]: a limit of the workspace.
type LimitReached struct {
	// A field of [Workspace.Limits]: "vcpus", "[Limits.LargestSize]" (max is that Size's number),
	// "[Limits.VolumeGib]", "[Limits.TemplateVersions]", "[Limits.TemplateGib]",
	// "[Limits.StartsPerMinute]", "[Limits.StartsPerHour]", "[Limits.StartsPerDay]"; or "secrets",
	// a bound of every workspace ([Client.SetSecret]).
	Limit string
	Max   int32
	// A starts_per_* limit: when enough of the window's starts have left it for the call to fit,
	// which may be retried then. Absent = never: a call that asks more starts than the limit.
	RetryTime time.Time
}

// Stopped is a detail of an [Error]: [Error.Stopped].
